    const edge = MathUtils.clamp((width - distance) * 260, 0, 1);
    const stalk = v < .12 && Math.abs(u - .5) < .008 ? 1 : 0;
    const alpha = Math.max(edge, stalk);
    const midrib = Math.exp(-Math.pow((u - center) * 115, 2));
    const branchVein = Math.exp(-Math.pow(Math.sin((v - Math.abs(u - center) * .57) * 68) * 11, 2));
    const mottling = 6 * Math.sin(x * .63 + Math.cos(y * .11)) + 3 * Math.cos(x * 1.7 + y * .42);
    const lift = 18 * midrib + 9 * branchVein + 14 * (1 - distance / .45);
    return [173 + lift + mottling, 194 + lift + mottling, 128 + lift + mottling, alpha * 255]
